import sys
import hashlib
import os

def compute_digest(file_path, key):
    try:
        with open(file_path, 'rb') as f:
            file_data = f.read()
            # Combine file data and key, then hash
            data = file_data + key
            digest = hashlib.sha256(data).digest()
            return digest
    except (OSError, IOError):
        return None

def main():
    if len(sys.argv) > 1 and sys.argv[1] == 'check':
        # Mode 2: check
        try:
            with open('manifest.txt', 'r') as f:
                lines = f.readlines()
        except FileNotFoundError:
            print("manifest.txt not found")
            sys.exit(1)

        try:
            with open('manifest.key', 'rb') as f:
                key = f.read(32)
        except FileNotFoundError:
            print("manifest.key not found")
            sys.exit(1)

        if not key or len(key) != 32:
            print("manifest.key must be exactly 32 bytes")
            sys.exit(1)

        errors = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            parts = line.split(' ', 1)
            if len(parts) != 2:
                continue
            path = parts[1]
            expected_digest_hex = parts[0]

            # Recompute digest
            digest = compute_digest(path, key)
            if digest is None:
                errors.append(f"{path} missing")
            else:
                digest_hex = digest.hex()
                if digest_hex != expected_digest_hex:
                    errors.append(f"{path} changed")

        if errors:
            for error in errors:
                print(error)
            sys.exit(1)
        else:
            sys.exit(0)

    else:
        # Mode 1: run command and generate manifest
        import subprocess

        # Read command from stdin
        command_line = sys.stdin.readline().strip()
        if not command_line:
            sys.exit(1)

        # Execute the command
        try:
            result = subprocess.run(
                command_line, 
                shell=True, 
                capture_output=True, 
                text=True, 
                check=False
            )
        except Exception as e:
            sys.exit(1)

        if result.returncode != 0:
            sys.exit(result.returncode)

        # Extract output lines
        output_lines = result.stdout.strip().split('\n')
        output_lines = [line.strip() for line in output_lines if line.strip()]

        # Read key
        try:
            with open('manifest.key', 'rb') as f:
                key = f.read(32)
        except FileNotFoundError:
            print("manifest.key not found")
            sys.exit(1)

        if not key or len(key) != 32:
            print("manifest.key must be exactly 32 bytes")
            sys.exit(1)

        # Generate manifest
        with open('manifest.txt', 'w') as f:
            for path in output_lines:
                digest = compute_digest(path, key)
                if digest is not None:
                    digest_hex = digest.hex()
                    f.write(f"{digest_hex} {path}\n")

        # Exit with success
        sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import sqlite3
import subprocess
import json

def main(config_xml, db_file):
    # Parse XML configuration
    tree = ET.parse(config_xml)
    root = tree.getroot()

    checks = []

    # Process each check element in order
    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        check_type = check_elem.get('type')

        if not name or not check_type:
            continue

        if check_type == 'command':
            command = check_elem.text.strip() if check_elem.text else ''
            if not command:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": ""
                })
                continue

            try:
                result = subprocess.run(
                    command, 
                    shell=True, 
                    capture_output=True, 
                    text=True, 
                    encoding='utf-8'
                )
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": str(e)
                })

        elif check_type == 'sql':
            sql_query = check_elem.text.strip() if check_elem.text else ''
            if not sql_query:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })
                continue

            try:
                conn = sqlite3.connect(db_file)
                cursor = conn.cursor()
                cursor.execute(sql_query)
                rows = cursor.fetchall()

                # Convert rows to JSON-compatible format
                json_rows = []
                for row in rows:
                    json_row = []
                    for value in row:
                        if value is None:
                            json_row.append(None)
                        elif isinstance(value, str):
                            json_row.append(value)
                        elif isinstance(value, int):
                            json_row.append(value)
                        elif isinstance(value, float):
                            json_row.append(value)
                        else:
                            json_row.append(str(value))
                    json_rows.append(json_row)

                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": json_rows
                })
                conn.close()

            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })

    # Output the JSON result
    print(json.dumps({"checks": checks}, indent=None))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(1)
    config_xml = sys.argv[1]
    db_file = sys.argv[2]
    main(config_xml, db_file)

