import sys
import re
import subprocess
import os

def evaluate_expression(expr, variables):
    try:
        # Replace variables with their values
        for var, value in variables.items():
            expr = expr.replace(f"{{{var}}}", str(value))

        # Evaluate the expression
        # We need to handle the expression safely
        # Using eval with restricted context
        result = eval(expr, {"__builtins__": {}}, {})
        return int(result)
    except Exception as e:
        return None

def main():
    # Read all input
    lines = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            lines.append(line)

    if not lines:
        sys.exit(1)

    # Parse variables
    variables = {}
    template = lines[0]

    # Extract name=integer pairs
    for line in lines[1:]:
        if '=' in line:
            name, value = line.split('=', 1)
            if value.strip().isdigit():
                variables[name.strip()] = int(value.strip())

    # Replace placeholders in template
    final_command = template
    placeholders = re.findall(r'\{\{([^}]+)\}\}', final_command)

    for placeholder in placeholders:
        # Evaluate the expression
        result = evaluate_expression(placeholder, variables)
        if result is None:
            sys.stderr.write(f"ERROR: expression {placeholder}\n")
            sys.exit(1)
        final_command = final_command.replace(f"{{{{{{{placeholder}}}}}}}", str(result))

    # Run the final command
    log_file = "runner.log"

    # Ensure log file exists
    if not os.path.exists(log_file):
        open(log_file, 'w').close()

    try:
        result = subprocess.run(final_command, shell=True, capture_output=True, text=True)
        # Append to log file
        with open(log_file, 'a') as f:
            f.write(f"RUN {final_command} exit {result.returncode}\n")

        if result.returncode == 0:
            sys.exit(0)
        else:
            sys.stderr.write(f"ERROR: exit {result.returncode}\n")
            sys.exit(1)

    except Exception as e:
        sys.stderr.write(f"ERROR: exit 1\n")
        sys.exit(1)

