        with open(cache_file, 'rb') as f:
            try:
                cache = json.load(f)
            except json.JSONDecodeError:
                cache = {}
    else:
        cache = {}

    # Process input lines
    lines = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            lines.append(line)

