            # Execute the command using subprocess without shell
            import subprocess
            result = subprocess.run(
                args,
                capture_output=True,
                text=True,
                check=False
            )
        except Exception as e:
            sys.exit(1)

        if result.returncode != 0:
            sys.exit(result.returncode)

        # Extract output lines
        output_lines = result.stdout.strip().split('\n')
        output_lines = [line.strip() for line in output_lines if line.strip()]

        # Read key
        try:
            with open('manifest.key', 'rb') as f:
                key = f.read(32)
        except FileNotFoundError:
            print("manifest.key not found")
            sys.exit(1)

        if not key or len(key) != 32:
            print("manifest.key must be exactly 32 bytes")
            sys.exit(1)

        # Generate manifest
        with open('manifest.txt', 'w') as f:
            for path in output_lines:
                digest = compute_digest(path, key)
                if digest is not None:
                    digest_hex = digest.hex()
                    f.write(f"{digest_hex} {path}\n")

        # Exit with success
        sys.exit(0)

