import requests
import os

def fetch_package_version(name):
    url = f"https://pypi.org/pypi/{name}/json"
    try:
        response = requests.get(url, timeout=10)
        if response.status_code != 200:
            return None
        data = response.json()
        if 'info' not in data or 'version' not in data['info']:
            return None
        return data['info']['version']
    except (requests.RequestException, json.JSONDecodeError):
        return None

def main():
    cache_file = 'cache.bin'
    report_file = 'report.txt'

    # Initialize cache if it doesn't exist
    if os.path.exists(cache_file):
        with open(cache_file, 'rb') as f:
            try:
                cache = json.load(f)
            except json.JSONDecodeError:
                cache = {}
    else:
        cache = {}

    # Process input lines
    lines = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            lines.append(line)

    # Generate report and update cache
    report_lines = []
    for name in lines:
        if name in cache:
            version = cache[name]
            report_lines.append(f"{name}\t{version}")
        else:
            version = fetch_package_version(name)
            if version:
                cache[name] = version
                with open(cache_file, 'w') as f:
                    json.dump(cache, f)
                report_lines.append(f"{name}\t{version}")
            else:
                report_lines.append(f"{name}\tERROR")

