import sys
import os
import random
import string
import ast

def read_data():
    file_path = "data.txt"
    if not os.path.exists(file_path):
        return {"users": {}, "sessions": {}}
    try:
        with open(file_path, "r") as file:
            data = file.read()
            # Use ast.literal_eval to safely evaluate the file content
            return ast.literal_eval(data)
    except (SyntaxError, ValueError, Exception):
        return {"users": {}, "sessions": {}}

def write_data(data):
    file_path = "data.txt"
    with open(file_path, "w") as file:
        file.write(str(data))

def generate_token():
    characters = string.digits + string.ascii_lowercase
    # Use random.choices for better security and clarity
    return ''.join(random.choices(characters, k=8))

def main():
    if len(sys.argv) < 3:
        print("Usage: python session_tool.py <command> <argument>")
        sys.exit(1)

    command = sys.argv[1]
    arg1 = sys.argv[2]

    data = read_data()

    if command == "login":
        if len(sys.argv) < 4:
            print("Usage: python session_tool.py login <username>")
            sys.exit(1)

        username = arg1
        password_line = sys.stdin.readline().strip()

        if username not in data["users"]:
            data["users"][username] = password_line
            write_data(data)
            print("registered")
            sys.exit(0)

        stored_password = data["users"][username]
        if stored_password == password_line:
            token = generate_token()
            data["sessions"][token] = username
            write_data(data)
            print(token)
            sys.exit(0)
        else:
            print("login failed")
            sys.exit(1)

    elif command == "check":
        if len(sys.argv) < 3:
            print("Usage: python session_tool.py check <token>")
            sys.exit(1)

        token = arg1
        if token in data["sessions"]:
            print(data["sessions"][token])
            sys.exit(0)
        else:
            print("no session")
            sys.exit(1)

    else:
        print("Usage: python session_tool.py login <username> | check <token>")
        sys.exit(1)

