import requests
import re
import ast

def evaluate_expression(expr):
    try:
        # Replace {{...}} with evaluated expression
        # Remove outer quotes and evaluate
        expr = expr.strip()
        if expr.startswith('0') and len(expr) == 1:
            return 0
        # Remove outer quotes if present
        expr = expr.strip()
        # Remove any leading/trailing whitespace
        expr = expr.strip()
        # Evaluate the expression safely using ast.literal_eval
        return int(ast.literal_eval(expr))
    except (ValueError, SyntaxError):
        raise ValueError(f"Invalid expression: {expr}")

def parse_query(query):
    # Replace {{...}} with evaluated expressions
    def replace_match(match):
        expr = match.group(1)
        try:
            # Evaluate the expression safely
            result = evaluate_expression(expr)
            return str(result)
        except Exception as e:
            raise ValueError(f"Error evaluating expression {expr}: {e}")

    # Find all {{...}} patterns
    pattern = r'\{\{([^}]+)\}\}'
    result = re.sub(pattern, replace_match, query)
    return result

def run_check(check):
    name = check["name"]
    db_path = check["db"]
    query = check["query"]
    threshold = check["threshold"]
    webhook = check["webhook"]

    # Parse and replace placeholders in query
    try:
        parsed_query = parse_query(query)
    except Exception as e:
        print(f"{name} {0} failed")
        return f"{name} {0} failed"

    # Connect to database and execute query
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(parsed_query)
        result = cursor.fetchone()
        if result is None:
            value = 0
        else:
            value = int(result[0])
        conn.close()
    except Exception as e:
        print(f"{name} {0} failed")
        return f"{name} {0} failed"

    # Determine outcome
    if value > threshold:
        try:
            response = requests.post(
                webhook,
                json={"check": name, "value": value},
                headers={"Content-Type": "application/json"},
                timeout=10  # Add timeout to prevent hanging requests
            )
            if response.status_code < 400:
                outcome = "sent"
            else:
                outcome = "failed"
        except requests.exceptions.RequestException:
            outcome = "failed"
    else:
        outcome = "skipped"

    return f"{name} {value} {outcome}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python alertcheck.py checks.json")
        sys.exit(1)

    json_path = sys.argv[1]

    try:
        with open(json_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading JSON file: {e}")
        sys.exit(1)

    checks = data.get("checks", [])

    for check in checks:
        result = run_check(check)
        print(result)

if __name__ == "__main__":
    main()

import sys
import json
import requests
import defusedxml
from defusedxml import ElementTree as ET

def parse_rss_xml(xml_content):
    try:
        root = ET.fromstring(xml_content)
        items = root.findall('.//{http://www.w3.org/2005/Atom}entry')
        if items:
            first_item = items[0]
            title = first_item.find('{http://www.w3.org/2005/Atom}title')
            link = first_item.find('{http://www.w3.org/2005/Atom}link')
            if title is not None and link is not None:
                return title.text, link.get('href')
        return None, None
    except Exception:
        return None, None

def main():
    if len(sys.argv) != 2:
        print(json.dumps({"feeds": []}))
        return

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(json.dumps({"feeds": []}))
        return

    if "feeds" not in config or not isinstance(config["feeds"], list):
        print(json.dumps({"feeds": []}))
        return

    result_feeds = []

    for feed in config["feeds"]:
        if not isinstance(feed, dict) or "name" not in feed or "url" not in feed:
            result_feeds.append({"name": feed.get("name", ""), "error": "failed"})
            continue

        name = feed["name"]
        url = feed["url"]

        try:
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                content = response.text
                # Check if it's RSS 2.0 XML
                if content.startswith('<?xml') and 'rss' in content.lower():
                    # Look for first <item> with <title> and <link>
                    root = ET.fromstring(content)
                    items = root.findall('.//item')
                    if items:
                        first_item = items[0]
                        title_elem = first_item.find('title')
                        link_elem = first_item.find('link')
                        if title_elem is not None and link_elem is not None:
                            title = title_elem.text
                            link = link_elem.text
                            result_feeds.append({
                                "name": name,
                                "title": title,
                                "link": link
                            })
                        else:
                            result_feeds.append({
                                "name": name,
                                "error": "failed"
                            })
                    else:
                        result_feeds.append({
                            "name": name,
                            "error": "failed"
                        })
                else:
                    result_feeds.append({
                        "name": name,
                        "error": "failed"
                    })
            else:
                result_feeds.append({
                    "name": name,
                    "error": "failed"
                })
        except Exception:
            result_feeds.append({
                "name": name,
                "error": "failed"
            })

    print(json.dumps({"feeds": result_feeds}))

if __name__ == "__main__":
    main()

import sys
import json
import os
import defusedxml.ElementTree as ET

def load_settings_from_xml(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
        settings = {}
        for entry in root.findall('entry'):
            key = entry.get('key')
            value = entry.get('value')
            if key is not None and value is not None:
                settings[key] = value
        return settings
    except Exception as e:
        return None

def load_settings_from_cache(cache_path):
    try:
        with open(cache_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:
        return None

def save_settings_to_cache(settings, cache_path):
    try:
        with open(cache_path, 'w', encoding='utf-8') as f:
            json.dump(settings, f, indent=2)
    except Exception as e:
        return False
    return True

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("error: missing argument\n")
        sys.exit(1)

    config_path = sys.argv[1]

    # Validate input path
    if not os.path.isfile(config_path):
        sys.stderr.write(f"error: {config_path}\n")
        sys.exit(1)

    # Create cache path
    cache_path = config_path + ".cache"

    # Try to load from cache first
    cached_settings = load_settings_from_cache(cache_path)
    if cached_settings is not None:
        sys.stdout.write(json.dumps(cached_settings, indent=2) + "\n")
        sys.stderr.write(f"source=cache\n")
        return

    # Load from XML
    settings = load_settings_from_xml(config_path)
    if settings is None:
        sys.stderr.write(f"error: {config_path}\n")
        sys.exit(1)

    # Save to cache
    if not save_settings_to_cache(settings, cache_path):
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

    # Output and report
    sys.stdout.write(json.dumps(settings, indent=2) + "\n")
    sys.stderr.write(f"source=xml\n")

if __name__ == "__main__":
    main()

