import sys
import urllib.request
import defusedxml.ElementTree as ET
import ast
import re

def evaluate_expression(expression):
    try:
        # Use ast.literal_eval for safe evaluation of expressions
        result = ast.literal_eval(expression)
        return float(result)
    except (ValueError, SyntaxError, TypeError) as e:
        raise ValueError(f"Invalid expression: {expression}")

def parse_config(config_path):
    feed_url = None
    threshold = None

    with open(config_path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key == 'feed_url':
                    feed_url = value
                elif key == 'threshold':
                    threshold = value
    return feed_url, threshold

def extract_price_sum(xml_content):
    root = ET.fromstring(xml_content)
    prices = []
    for elem in root.iter():
        if elem.tag == 'price':
            try:
                price = float(elem.text)
                prices.append(price)
            except (ValueError, TypeError):
                continue
    return sum(prices)

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file_path>")
        sys.exit(1)

    config_path = sys.argv[1]
    feed_url, threshold_str = parse_config(config_path)

    if not feed_url:
        print("Error: feed_url is missing in configuration file")
        sys.exit(1)

    if not threshold_str:
        print("Error: threshold is missing in configuration file")
        sys.exit(1)

    # Validate URL scheme to ensure only safe schemes (e.g., http, https) are used
    if not (feed_url.startswith('http://') or feed_url.startswith('https://')):
        print("Error: Invalid URL scheme. Only http or https are allowed.")
        sys.exit(1)

    try:
        with urllib.request.urlopen(feed_url) as response:
            xml_content = response.read().decode('utf-8')
    except Exception as e:
        print(f"Error fetching feed URL: {e}")
        sys.exit(1)

    try:
        price_sum = extract_price_sum(xml_content)
        threshold_value = evaluate_expression(threshold_str)

        if price_sum > threshold_value:
            print("OK")
        else:
            print("LOW")
    except Exception as e:
        print(f"Error processing data: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

