import sys
import requests
import re
from urllib.parse import quote

def main():
    print("Package file: ", end="")
    package_file_path = input().strip()

    # Validate input path
    if not package_file_path or not package_file_path.strip():
        print("Invalid input path")
        sys.exit(1)

    # Validate and sanitize package names
    package_names = []
    try:
        with open(package_file_path, 'r', encoding='utf-8') as file:
            for line_num, line in enumerate(file, 1):
                line = line.strip()
                if not line:
                    continue
                # Validate package name: only allow alphanumeric, hyphens, underscores, dots
                if not re.match(r'^[a-zA-Z0-9._-]+$', line):
                    print(f"Invalid package name on line {line_num}: '{line}'")
                    continue
                package_names.append(line)
    except FileNotFoundError:
        print(f"Error: File '{package_file_path}' not found")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied when reading file '{package_file_path}'")
        sys.exit(1)

    if not package_names:
        print("No valid package names found")
        sys.exit(1)

    output_lines = []

    # Rate limiting: add a small delay between requests to avoid overwhelming the server
    import time
    delay = 0.5  # 500ms delay between requests

    for package_name in package_names:
        url = f"https://pypi.org/pypi/{quote(package_name)}/json"
        try:
            # Add a small delay to prevent rate flooding
            time.sleep(delay)

            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                try:
                    data = response.json()
                    # Validate that required field exists and version is a string
                    if 'info' in data and 'version' in data['info']:
                        version = data['info']['version']
                        # Validate version format (basic alphanumeric with dots and hyphens)
                        if re.match(r'^[0-9]+(\.[0-9]+(\.[0-9]+)?)?(\-[0-9]+)?$', version):
                            output_lines.append(f"{package_name}=={version}")
                        else:
                            output_lines.append(f"{package_name}: invalid version")
                    else:
                        output_lines.append(f"{package_name}: unavailable")
                except (KeyError, TypeError, ValueError) as e:
                    output_lines.append(f"{package_name}: unavailable")
            else:
                output_lines.append(f"{package_name}: unavailable")

        except requests.exceptions.Timeout:
            output_lines.append(f"{package_name}: unavailable")
        except requests.exceptions.ConnectionError:
            output_lines.append(f"{package_name}: unavailable")
        except requests.exceptions.RequestException as e:
            output_lines.append(f"{package_name}: unavailable")
        except Exception as e:
            output_lines.append(f"{package_name}: unavailable")

    # Print to stdout
    for line in output_lines:
        print(line)

    # Write to file with proper encoding
    try:
        with open('latest_versions.txt', 'w', encoding='utf-8') as file:
            for line in output_lines:
                file.write(line + '\n')
    except PermissionError:
        print(f"Error: Permission denied when writing to 'latest_versions.txt'")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
from xml.parsers.expat import ExpatError

def parse_xml_with_entities(file_path, item_name):
    # Validate file path to prevent path traversal
    import os
    # Normalize and validate the path
    if not file_path or not isinstance(file_path, str):
        return "ERROR"

    # Ensure the path is absolute and within a safe directory
    # For security, we restrict to the current directory only
    if not file_path.startswith('/'):
        # If relative, ensure it's in the current directory
        if not file_path.startswith('./') and not file_path.startswith('../'):
            file_path = './' + file_path

    # Normalize path and check for traversal
    normalized_path = os.path.normpath(file_path)
    if '..' in normalized_path or '~' in normalized_path:
        return "ERROR"

    # Check if the path is within the current directory
    if not normalized_path.startswith('./'):
        return "ERROR"

    # Validate the file exists and is readable
    try:
        with open(normalized_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except (OSError, IOError):
        return "ERROR"

    # Parse XML with entity resolution disabled for external entities
    # We use a custom parser that disables external entity resolution
    try:
        # Create a parser that does not resolve external entities
        parser = ET.XMLParser(encoding='utf-8', resolve_entities=False)
        root = ET.fromstring(content, parser=parser)
    except (ExpatError, ET.ParseError):
        return "ERROR"

    # Find the first item with the given name
    for item in root.findall('item'):
        if item.get('name') == item_name:
            value = item.get('value')
            if value is not None:
                # Since we disabled external entities, no entity resolution occurs
                # The value is already safe
                return value

    return "NOT_FOUND"

def main():
    try:
        file_path = sys.stdin.readline().strip()
        item_name = sys.stdin.readline().strip()

        if not file_path or not item_name:
            print("ERROR")
            sys.exit(1)

        result = parse_xml_with_entities(file_path, item_name)
        print(result)

    except Exception as e:
        print("ERROR")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET

def xml_config_to_json(xml_file):
    try:
        # Explicitly disable external entity resolution to prevent XXE attacks
        parser = ET.XMLParser(resolve_entities=False)
        tree = ET.parse(xml_file, parser)
        root = tree.getroot()

        result = {}

        for child in root:
            tag_name = child.tag
            value = None

            # Check for 'value' attribute
            if child.get('value') is not None:
                value = child.get('value')
            else:
                # Use text content with leading and trailing whitespace removed
                text = child.text.strip() if child.text is not None else ""
                value = text

            result[tag_name] = value

        # Print JSON object with 2 spaces indentation and newline
        import json
        print(json.dumps(result, indent=2))

    except ET.ParseError:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_config_to_json(sys.argv[1])

import json
