    return True

def parse_expression(expr, bindings):
    """Parse and evaluate a safe expression with restricted operations."""
    try:
        # Validate expression string before parsing
        if not expr or not isinstance(expr, str):
            raise ValueError("Invalid expression")

        # Validate expression content using a simple regex-like check
        # Only allow digits, letters, underscores, +, -, *, (, )
        import re
        if not re.match(r'^[0-9+\-*/()_a-zA-Z]+$', expr):
