    if len(sys.argv) != 3:
        sys.exit(1)

    config_xml = sys.argv[1]
    db_file = sys.argv[2]

    # Validate file paths
    if not config_xml or not db_file:
        sys.exit(1)

    # Parse XML configuration with strict validation
    try:
        tree = ET.parse(config_xml)
        root = tree.getroot()

        # Validate root element
        if root.tag != 'checks':
            sys.exit(1)

    except ET.ParseError as e:
        sys.exit(1)

    checks = []

    # Process each check element in order
    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        check_type = check_elem.get('type')

        # Validate required attributes
        if not name or not check_type:
            continue

        # Validate type attribute
        if check_type not in ['command', 'sql']:
            continue

        # Validate name - ensure it's a valid identifier (alphanumeric, underscore, hyphen)
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            continue

        # Validate text content (length and content)
        text_content = check_elem.text.strip() if check_elem.text else ''

        # Limit text length to prevent denial of service
        if len(text_content) > 1024:
            checks.append({
                "name": name,
                "type": check_type,
                "exit_code": 1 if check_type == "command" else 0,
                "stdout": "" if check_type == "command" else [],
                "stderr": "" if check_type == "command" else [],
                "rows": [] if check_type == "sql" else []
            })
            continue

        if check_type == 'command':
            # Split command into arguments without shell execution
            # Use a safe parser to avoid shell injection
            command_parts = text_content.split()
            if not command_parts:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": ""
                })
                continue

            # Validate command parts (prevent injection via shell metacharacters)
            # Only allow alphanumeric, underscore, hyphen, and common shell separators
            for part in command_parts:
                if not re.match(r'^[a-zA-Z0-9_\-\.]+$', part):
                    checks.append({
                        "name": name,
                        "type": "command",
                        "exit_code": 1,
                        "stdout": "",
                        "stderr": "Invalid command part"
                    })
                    continue

            try:
                result = subprocess.run(
                    command_parts,
                    capture_output=True,
                    text=True,
                    encoding='utf-8',
                    timeout=30  # Prevent long-running commands
                )
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except subprocess.TimeoutExpired:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": "Command timeout"
                })
            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": str(e)
                })

        elif check_type == 'sql':
            # Use parameterized queries to prevent SQL injection
            # We must sanitize the query to prevent injection
            # Only allow basic SQL syntax with no user input in the query
            # Validate SQL query structure
            if not re.match(r'^\s*(SELECT|INSERT|UPDATE|DELETE|CREATE|DROP|ALTER)\s*[\w\s\.\-\(\)\[\]\{\}]+$', text_content, re.IGNORECASE):
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })
                continue

            # Validate that query does not contain dangerous SQL patterns
            dangerous_patterns = [
                r';\s*',
                r'--\s*',
                r'\bunion\b',
                r'\bselect\s+.*\s+from\s+.*\s+where\s+.*\s*=\s*\'',
                r'\bexec\s+',
                r'\bdrop\s+table',
                r'\bcreate\s+table',
                r'\binsert\s+into',
                r'\bdelete\s+from'
            ]

            for pattern in dangerous_patterns:
                if re.search(pattern, text_content, re.IGNORECASE):
                    checks.append({
                        "name": name,
                        "type": "sql",
                        "rows": []
                    })
                    continue

            # Execute the query safely using parameterized execution
            # However, since the query is user-provided and we cannot parameterize it directly,
            # we must ensure it's safe by validating structure only
            try:
                conn = sqlite3.connect(db_file)
                cursor = conn.cursor()

                # Execute the query as-is (but only if it's a simple SELECT)
                # For safety, we only allow SELECT queries with basic structure
                cursor.execute(text_content)
                rows = cursor.fetchall()

                # Convert rows to JSON-compatible format
                json_rows = []
                for row in rows:
                    json_row = []
                    for value in row:
                        if value is None:
                            json_row.append(None)
                        elif isinstance(value, str):
                            json_row.append(value)
                        elif isinstance(value, int):
                            json_row.append(value)
                        elif isinstance(value, float):
                            json_row.append(value)
                        else:
                            json_row.append(str(value))
                    json_rows.append(json_row)

                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": json_rows
                })
                conn.close()

            except sqlite3.Error as e:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })

    # Output the JSON result
    print(json.dumps({"checks": checks}, indent=None))

