    main()

import sys
import re
from ast import parse, NodeVisitor, Node, literal_eval

def safe_eval_expression(expression, quantity):
    """
    Safely evaluate a mathematical expression with variable q.
    Only allows numeric literals, q, +, -, *, /, and parentheses.
    """
    # Validate expression structure using AST
    try:
        # Parse the expression to ensure it only contains allowed elements
        tree = parse(expression.replace('q', 'q'), mode='eval')

        # Validate the AST node structure
        class ExpressionValidator(NodeVisitor):
            def visit_BinOp(self, node):
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                    raise ValueError("Unsupported operator")
                self.generic_visit(node)
            def visit_Num(self, node):
                pass
            def visit_Name(self, node):
                if node.id != 'q':
                    raise ValueError("Invalid variable name")
            def visit_UnaryOp(self, node):
                raise ValueError("Unsupported unary operation")
            def visit_Compare(self, node):
                raise ValueError("Unsupported comparison")
            def visit_Call(self, node):
                raise ValueError("Function call not allowed")
            def visit_Attribute(self, node):
                raise ValueError("Attribute access not allowed")
            def visit_Subscript(self, node):
                raise ValueError("Subscript access not allowed")
            def visit_BoolOp(self, node):
                raise ValueError("Boolean operations not allowed")
            def visit_Starred(self, node):
                raise ValueError("Starred expressions not allowed")
            def visit_ExceptHandler(self, node):
                raise ValueError("Exception handling not allowed")
            def visit_With(self, node):
                raise ValueError("With statement not allowed")
            def visit_AnnAssign(self, node):
                raise ValueError("Annotation assignment not allowed")
            def visit_Assign(self, node):
                raise ValueError("Assignment not allowed")
            def visit_AugAssign(self, node):
                raise ValueError("Augmented assignment not allowed")
            def visit_Return(self, node):
                raise ValueError("Return statement not allowed")
            def visit_If(self, node):
                raise ValueError("If statement not allowed")
            def visit_For(self, node):
                raise ValueError("For loop not allowed")
            def visit_While(self, node):
                raise ValueError("While loop not allowed")
            def visit_FunctionDef(self, node):
                raise ValueError("Function definition not allowed")
            def visit_ClassDef(self, node):
                raise ValueError("Class definition not allowed")
            def visit_With(self, node):
                raise ValueError("With statement not allowed")
            def visit_Dict(self, node):
                raise ValueError("Dictionary not allowed")
            def visit_Set(self, node):
                raise ValueError("Set not allowed")
            def visit_List(self, node):
                raise ValueError("List not allowed")
            def visit_Tuple(self, node):
                raise ValueError("Tuple not allowed")
            def visit_Starred(self, node):
                raise ValueError("Starred expression not allowed")

        validator = ExpressionValidator()
        validator.visit(tree)

        # Replace q with quantity in a safe way
        # We already validated the structure, so we can evaluate safely
        expr_with_q = expression.replace('q', str(quantity))

        # Evaluate the expression using safe literal evaluation
        # Since we've validated the AST, we can now safely evaluate
        result = eval(expr_with_q, {"__builtins__": {}}, {})

        # Ensure result is a number
        if isinstance(result, (int, float)):
            if result == int(result):
                return str(int(result))
            else:
                return f"{result:.1f}"
        else:
            raise ValueError("Expression evaluated to non-numeric value")

    except Exception as e:
        # If validation fails or evaluation fails, return the quantity as string
        return str(quantity)

def main():
    # Read the first line as the template path
    template_path = sys.stdin.readline().strip()

    # Read remaining lines as records
    records = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            parts = line.split(',', 2)
            if len(parts) == 3:
                name, quantity_str, expression = parts
                quantity = int(quantity_str)
                records.append((name, quantity, expression))

    # Read the template file
    try:
        with open(template_path, 'r') as f:
            template_content = f.read()
    except FileNotFoundError:
        # If template file not found, output empty HTML
        print("")
        return

    # Replace {{rows}} with table rows
    rows_html = ""
    for name, quantity, expression in records:
        value = safe_eval_expression(expression, quantity)
        row = f"<tr><td>{name}</td><td>{value}</td></tr>"
        rows_html += row + "\n"

    # Replace {{rows}} in template
    result = template_content.replace('{{rows}}', rows_html)

    # Output the result
    print(result)

