import sys
import xml.etree.ElementTree as ET
import subprocess
import os

def main():
    if len(sys.argv) != 2:
        print("config failed: incorrect number of arguments", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"config failed: {e}", file=sys.stderr)
        sys.exit(1)

    if root.tag != 'job':
        print("config failed: root element is not <job>", file=sys.stderr)
        sys.exit(1)

    command = root.get('command')
    logfile = root.get('logfile')

    if not command or not logfile:
        print("config failed: missing command or logfile attribute", file=sys.stderr)
        sys.exit(1)

    try:
        with open(logfile, 'w') as log:
            result = subprocess.run(command, shell=True, stdout=log, stderr=sys.stderr, text=True)
    except Exception as e:
        print(f"job failed: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"job exited with code {result.returncode}", file=sys.stderr)

    if result.returncode == 0:
        sys.exit(0)
    else:
        sys.exit(1)

