import sys
import re
import subprocess
import os

def evaluate_expression(expr, variables):
    try:
        return str(eval(expr, {}, variables))
    except:
        return None

def main():
    lines = sys.stdin.read().splitlines()
    template = lines[0]
    variables = {}

    for line in lines[1:]:
        if line:
            name, value = line.split('=')
            variables[name] = int(value)

    placeholders = re.findall(r'\{\{(.*?)\}\}', template)
    for placeholder in placeholders:
        result = evaluate_expression(placeholder, variables)
        if result is None:
            sys.stderr.write(f"ERROR: expression {placeholder}\n")
            sys.exit(1)
        template = template.replace(f"{{{{{placeholder}}}}}", result)

    try:
        process = subprocess.Popen(template, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode

        with open('runner.log', 'a') as log_file:
            log_file.write(f"RUN {template} exit {exit_code}\n")

        if exit_code != 0:
            sys.stderr.write(f"ERROR: exit {exit_code}\n")
            sys.exit(1)

    except Exception as e:
        sys.stderr.write(f"ERROR: {str(e)}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

