import os
import sys
import hashlib
import json
import requests

def main():
    manifest = []
    manifest_key = os.getenv('MANIFEST_KEY')
    if not manifest_key:
        sys.exit(1)

    for line in sys.stdin:
        path = line.strip()
        if not path:
            continue

        try:
            size = os.path.getsize(path)
            name = os.path.basename(path)
            with open(path, 'rb') as f:
                file_bytes = f.read()
            digest = hashlib.sha256(file_bytes + manifest_key.encode()).hexdigest()
            manifest.append({'name': name, 'size': size, 'digest': digest})
        except OSError:
            continue

    with open('manifest.json', 'w', encoding='utf-8') as f:
        json.dump(manifest, f, ensure_ascii=False)

    endpoint = os.getenv('MANIFEST_ENDPOINT')
    if not endpoint:
        sys.exit(1)

    try:
        response = requests.post(endpoint, json=manifest, headers={'Content-Type': 'application/json'}, timeout=10)
        if 200 <= response.status_code < 300:
            print(response.text)
        else:
            sys.exit(1)
    except requests.RequestException:
        sys.exit(1)

