    except (ValueError, SyntaxError):
        raise ValueError("Invalid expression")

def process_steps(steps):
    pattern = r'\{\{([^{}]+)\}\}'
    for step in steps:
        processed = re.sub(pattern, lambda m: str(evaluate_expression(m.group(1))), step)
        print(processed)

def main():
    if len(sys.argv) != 2:
        print("Usage: python taskrun.py <file_path>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
