import sys
import json
import subprocess
import os
import html
import shlex

def load_state():
    if os.path.exists('report_state.json'):
        with open('report_state.json', 'r') as f:
            return json.load(f)
    return {}

def save_state(state):
    with open('report_state.json', 'w') as f:
        json.dump(state, f, indent=2)

def run_command(command):
    try:
        process = subprocess.Popen(shlex.split(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()
        return process.returncode, stdout, stderr
    except Exception as e:
        return -1, '', str(e)

def sanitize_html(text):
    return html.escape(text)

def main(jobs_file, report_file):
    if not os.path.isfile(jobs_file):
        print(f"Error: The file '{jobs_file}' does not exist.")
        sys.exit(1)

    try:
        with open(jobs_file, 'r') as f:
            jobs_data = json.load(f)
    except json.JSONDecodeError:
        print(f"Error: The file '{jobs_file}' contains invalid JSON.")
        sys.exit(1)

    if 'jobs' not in jobs_data or not isinstance(jobs_data['jobs'], list):
        print(f"Error: The file '{jobs_file}' does not contain a valid 'jobs' array.")
        sys.exit(1)

    jobs = jobs_data['jobs']
    state = load_state()

    for job in jobs:
        if not isinstance(job, dict) or 'name' not in job or 'command' not in job:
            print(f"Error: Job in '{jobs_file}' is missing required fields.")
            continue

        name = job['name']
        command = job['command']

        if name in state:
            exit_code = state[name]['exit_code']
            stdout = state[name]['stdout']
            stderr = state[name]['stderr']
        else:
            exit_code, stdout, stderr = run_command(command)
            state[name] = {
                'exit_code': exit_code,
                'stdout': stdout,
                'stderr': stderr
            }

    save_state(state)

    try:
        with open(report_file, 'w') as f:
            f.write('<!DOCTYPE html>\n<html>\n<head>\n<title>Job Report</title>\n</head>\n<body>\n')
            f.write('<h1>Job Report</h1>\n')
            f.write('<table border="1">\n')
            f.write('<tr><th>Name</th><th>Exit code</th><th>Stdout</th><th>Stderr</th></tr>\n')

            for job in jobs:
                name = job['name']
                job_state = state[name]
                f.write(f'<tr><td>{sanitize_html(name)}</td><td>{job_state["exit_code"]}</td><td>{sanitize_html(job_state["stdout"])}</td><td>{sanitize_html(job_state["stderr"])}</td></tr>\n')

            f.write('</table>\n')
            f.write('</body>\n</html>\n')
    except IOError:
        print(f"Error: Unable to write to the report file '{report_file}'.")
        sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python build_report.py <jobs_file> <report_file>')
        sys.exit(1)

    jobs_file = sys.argv[1]
    report_file = sys.argv[2]
    main(jobs_file, report_file)

import os
import sys
import json
import time
import subprocess
import requests
from requests.exceptions import RequestException
import shlex
import logging

def load_config(config_path):
    with open(config_path, 'r') as file:
        config = json.load(file)
    required_keys = {"api_base_url", "token_env_var", "working_dir", "timeout_seconds"}
    if not required_keys.issubset(config.keys()):
        raise ValueError("Configuration file is missing required keys.")
    return config

def fetch_pending_jobs(api_base_url, token):
    headers = {'Authorization': f'Bearer {token}'}
    try:
        response = requests.get(f'{api_base_url}/jobs?status=pending', headers=headers, verify=True)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or 'jobs' not in data or not isinstance(data['jobs'], list):
            raise ValueError("Invalid response format from API.")
        return data['jobs']
    except RequestException as e:
        logging.error(f"Failed to fetch pending jobs: {e}")
        sys.exit(1)

def run_command(command, working_dir, timeout_seconds):
    try:
        result = subprocess.run(
            shlex.split(command),
            cwd=working_dir,
            capture_output=True,
            text=True,
            timeout=timeout_seconds
        )
        return {
            'exit_code': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr,
            'timed_out': False
        }
    except subprocess.TimeoutExpired:
        return {
            'exit_code': None,
            'stdout': '',
            'stderr': '',
            'timed_out': True
        }
    except Exception as e:
        logging.error(f"Error running command '{command}': {e}")
        return {
            'exit_code': None,
            'stdout': '',
            'stderr': str(e),
            'timed_out': False
        }

def report_result(api_base_url, token, job_id, result):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }
    try:
        response = requests.post(
            f'{api_base_url}/jobs/{job_id}/result',
            headers=headers,
            json=result,
            verify=True
        )
        response.raise_for_status()
    except RequestException as e:
        logging.error(f"Failed to report result for job {job_id}: {e}")

def main():
    logging.basicConfig(level=logging.INFO)
    if len(sys.argv) != 2:
        print("Usage: CI_API_TOKEN=abc123 python jobrunner.py config.json")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        config = load_config(config_path)
    except (IOError, json.JSONDecodeError, ValueError) as e:
        logging.error(f"Failed to load configuration: {e}")
        sys.exit(1)

    api_base_url = config['api_base_url']
    token_env_var = config['token_env_var']
    working_dir = os.path.abspath(config['working_dir'])
    timeout_seconds = config['timeout_seconds']

    token = os.getenv(token_env_var)
    if not token:
        logging.error(f"Environment variable {token_env_var} not set.")
        sys.exit(1)

    jobs = fetch_pending_jobs(api_base_url, token)
    for job in jobs:
        job_id = job['id']
        command = job['command']
        result = run_command(command, working_dir, timeout_seconds)
        report_result(api_base_url, token, job_id, result)
        if result['timed_out']:
            print(f"{job_id} timeout")
        else:
            print(f"{job_id} {result['exit_code']}")

if __name__ == '__main__':
    main()

import sys
import xml.etree.ElementTree as ET
import subprocess
import requests
import json
import os
import re

def validate_command(command):
    # Allow only alphanumeric characters, spaces, and basic shell operators
    if not re.match(r'^[a-zA-Z0-9\s\.\-_/\\:]+$', command):
        raise ValueError("Invalid command")

def validate_url(url):
    # Basic URL validation
    if not re.match(r'^https?://', url):
        raise ValueError("Invalid URL")

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_services.py <config_path>")
        sys.exit(1)

    config_path = sys.argv[1]

    # Prevent XML External Entity (XXE) Injection
    parser = ET.XMLParser(forbid_dtd=True)
    try:
        tree = ET.parse(config_path, parser=parser)
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}")
        sys.exit(1)

    root = tree.getroot()

    services_status = {}

    for service in root.findall('service'):
        name = service.get('name')
        if not name:
            print("Service name is missing")
            continue

        command_elem = service.find('command')
        url_elem = service.find('url')

        if command_elem is None or url_elem is None:
            print(f"Missing command or URL for service: {name}")
            continue

        command = command_elem.text
        url = url_elem.text

        if not command or not url:
            print(f"Empty command or URL for service: {name}")
            continue

        try:
            validate_command(command)
            validate_url(url)
        except ValueError as e:
            print(f"Validation error for service {name}: {e}")
            continue

        # Run the command and get the exit code
        try:
            result = subprocess.run(command, shell=False, capture_output=True, text=True)
            exit_code = result.returncode
        except subprocess.SubprocessError as e:
            print(f"Error running command for service {name}: {e}")
            exit_code = None

        # Request the URL and get the HTTP status code
        try:
            response = requests.get(url, timeout=10, verify=True)
            http_status = response.status_code
        except requests.RequestException as e:
            print(f"Error requesting URL for service {name}: {e}")
            http_status = None

        services_status[name] = {
            'exit_code': exit_code,
            'http_status': http_status
        }

    print(json.dumps(services_status))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import subprocess
import re

def is_valid_expression(expr):
    # Only allow integers, 'value', parentheses, and the operators + and *
    return re.match(r'^(\d+|value|\s*[()+\-*/]\s*)*$', expr) is not None

def main():
    if len(sys.argv) != 2:
        print("Usage: python program.py <xml_file>")
        return

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print("Error: Could not parse the XML file.")
        return
    except FileNotFoundError:
        print("Error: XML file not found.")
        return

    for task in root.findall('task'):
        name = task.get('name')
        command = task.find('command').text
        expr = task.find('expr').text

        if not is_valid_expression(expr):
            print(f"{name}: error")
            continue

        try:
            result = subprocess.run(command, shell=False, check=True, capture_output=True, text=True)
            value = int(result.stdout.strip())
            result = eval(expr, {"value": value})
            if not isinstance(result, int):
                raise ValueError("Expression did not evaluate to an integer.")
        except (subprocess.CalledProcessError, ValueError, TypeError, SyntaxError):
            result = "error"

        print(f"{name}: {result}")

if __name__ == "__main__":
