    except subprocess.CalledProcessError as e:
        return job_id, e.returncode

def validate_and_sanitize_command(command):
    # Basic validation: ensure command is a non-empty string
    if not isinstance(command, str) or not command.strip():
        raise ValueError("Invalid command")
    # Further sanitization: allow only alphanumeric characters, spaces, and basic shell syntax
    if not all(c.isalnum() or c in ' ._/' for c in command):
        raise ValueError("Command contains invalid characters")
    return command.split()

def parse_xml_safe(xml_file):
    try:
        tree = ET.parse(xml_file)
        return tree.getroot()
    except ParseError:
        raise ValueError("Malformed XML")
    except FileNotFoundError:
        raise ValueError("XML file not found")

def main():
    parser = argparse.ArgumentParser(description='Run jobs from an XML file.')
    parser.add_argument('xml_file', help='Path to the XML file containing jobs')
    parser.add_argument('--max-parallel', type=int, required=True, help='Maximum number of parallel jobs')
    args = parser.parse_args()

