import sys
import re
import subprocess
import os
import ast
import operator

# Define a safe eval function
def safe_eval(expr, variables):
    # Supported operators
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.BitXor: operator.xor,
        ast.USub: operator.neg
    }

    # Supported nodes
    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return operators[type(node.op)](operand)
        else:
            raise TypeError(f"Unsupported operation: {type(node).__name__}")

    # Parse the expression
    tree = ast.parse(expr, mode='eval')
    return eval_node(tree.body)

def evaluate_expression(expr, variables):
    try:
        return str(safe_eval(expr, variables))
    except Exception as e:
        return None

def main():
    lines = sys.stdin.read().splitlines()
    template = lines[0]
    variables = {}

    for line in lines[1:]:
        if line:
            name, value = line.split('=')
            if not name.isidentifier():
                sys.stderr.write(f"ERROR: invalid variable name {name}\n")
                sys.exit(1)
            try:
                variables[name] = int(value)
            except ValueError:
                sys.stderr.write(f"ERROR: invalid integer value {value}\n")
                sys.exit(1)

    placeholders = re.findall(r'\{\{(.*?)\}\}', template)
    for placeholder in placeholders:
        result = evaluate_expression(placeholder, variables)
        if result is None:
            sys.stderr.write(f"ERROR: expression {placeholder}\n")
            sys.exit(1)
        template = template.replace(f"{{{{{placeholder}}}}}", result)

    try:
        process = subprocess.Popen(template, shell=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode

        with open('runner.log', 'a') as log_file:
            log_file.write(f"RUN {template} exit {exit_code}\n")

        if exit_code != 0:
            sys.stderr.write(f"ERROR: exit {exit_code}\n")
            sys.exit(1)

    except Exception as e:
        sys.stderr.write(f"ERROR: {str(e)}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

