def main():
    if len(sys.argv) != 2:
        print("Usage: python contact_find.py <database_path>")
        return

    database_path = sys.argv[1]
    if not os.path.isfile(database_path):
        print("Invalid database path.")
        return

    cache_path = f"{database_path}.cache"

