import urllib.parse

def fetch_latest_version(package_name):
    try:
        url = f"https://pypi.org/pypi/{urllib.parse.quote(package_name)}/json"
        context = ssl.create_default_context()
        context.check_hostname = True
        context.verify_mode = ssl.CERT_REQUIRED
        request = urllib.request.Request(url, timeout=10)
        with urllib.request.urlopen(request, context=context) as response:
            data = json.loads(response.read().decode())
            return data['info']['version']
    except (urllib.error.URLError, json.JSONDecodeError, KeyError, ssl.SSLError, TimeoutError):
        return None

def load_cache():
    if os.path.exists('cache.bin'):
        with open('cache.bin', 'rb') as f:
            return pickle.loads(f.read())
    return {}

def save_cache(cache):
    with open('cache.bin', 'wb') as f:
        f.write(pickle.dumps(cache))

def main():
    cache = load_cache()
    results = []

    for line in sys.stdin:
        package_name = line.strip()
        if not package_name:
            continue

        if package_name in cache:
            version = cache[package_name]
        else:
            version = fetch_latest_version(package_name)
            if version:
                cache[package_name] = version

        if version:
            results.append(f"{package_name}\t{version}")
        else:
            results.append(f"{package_name}\tERROR")

    save_cache(cache)

    with open('report.txt', 'w') as f:
        for result in results:
            f.write(result + '\n')

if __name__ == "__main__":
    main()

import sys
import os
import json
import secrets
import string

DATA_FILE = 'data.txt'

def load_data():
    if not os.path.exists(DATA_FILE):
        return {"users": {}, "sessions": {}}
    with open(DATA_FILE, 'r') as file:
        return json.load(file)

def save_data(data):
    with open(DATA_FILE, 'w') as file:
        json.dump(data, file)
    os.chmod(DATA_FILE, 0o600)  # Set file permissions to read/write for owner only

def generate_token():
    return secrets.token_urlsafe(8)  # Use a cryptographically secure token generator

def validate_input(input_str):
    if not input_str or any(c in input_str for c in '\n\r\t'):
        raise ValueError("Invalid input")

def main():
    if len(sys.argv) < 3:
        print("Usage: python session_tool.py <command> <argument>")
        sys.exit(1)

    command = sys.argv[1]
    argument = sys.argv[2]

    try:
        validate_input(argument)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    data = load_data()

    if command == 'login':
        username = argument
        password = sys.stdin.readline().rstrip('\n')

        try:
            validate_input(password)
        except ValueError as e:
            print(f"Error: {e}")
            sys.exit(1)

        if username not in data['users']:
            data['users'][username] = password
            save_data(data)
            print("registered")
            sys.exit(0)
        elif data['users'][username] == password:
            token = generate_token()
            data['sessions'][token] = username
            save_data(data)
            print(token)
            sys.exit(0)
        else:
            print("login failed")
            sys.exit(1)

    elif command == 'check':
        token = argument
        if token in data['sessions']:
