import sys
import sqlite3
import xml.etree.ElementTree as ET
import requests
from datetime import datetime
import re

def validate_date(date_text):
    try:
        datetime.strptime(date_text, '%Y-%m-%d')
        return True
    except ValueError:
        return False

def parse_xml_safe(file_path):
    parser = ET.XMLParser(forbid_dtd=True)
    try:
        tree = ET.parse(file_path, parser=parser)
        return tree.getroot()
    except ET.ParseError:
        print("Error: Could not parse sync.xml")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python sync_users.py <date>")
        sys.exit(1)

    since = sys.argv[1]
    if not validate_date(since):
        print("Error: Invalid date format. Use YYYY-MM-DD.")
        sys.exit(1)

    root = parse_xml_safe('sync.xml')

    db_file = root.find('database').get('file')
    query = root.find('query').text
    endpoint_url = root.find('endpoint').get('url')

    if not re.match(r'^https://', endpoint_url):
        print("Error: Endpoint URL must use HTTPS.")
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
        cursor.execute(query, (since,))
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)
    finally:
        if conn:
            conn.close()

    all_ok = True
    for row in rows:
        user_id, email = row
        payload = {"id": user_id, "email": email}
        headers = {"Content-Type": "application/json"}

        try:
            response = requests.post(endpoint_url, json=payload, headers=headers, verify=True)
            if response.status_code == 200:
                print(f"ok {user_id}")
            else:
                print(f"fail {user_id} {response.status_code}")
                all_ok = False
        except requests.RequestException as e:
            print(f"Request error for user {user_id}: {e}")
            all_ok = False

    sys.exit(0 if all_ok else 1)

if __name__ == "__main__":
    main()

import sys
import sqlite3
import requests
from html import escape
import os
import re
import time

def validate_status_value(status_value):
    # Ensure the status value is alphanumeric to prevent SQL injection
    if not re.match(r'^[a-zA-Z0-9]+$', status_value):
        raise ValueError("Invalid status value")

def validate_file_path(file_path):
    # Ensure the file path is safe and within the expected directory
    if not os.path.isabs(file_path):
        raise ValueError("Output path must be an absolute path")
    if not file_path.startswith('/safe/output/directory/'):
        raise ValueError("Output path is not within the allowed directory")

def main():
    if len(sys.argv) != 3:
        print("Usage: python linkreport.py <db_path> <output_path>")
        sys.exit(1)

    db_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        validate_file_path(output_path)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    status_value = input().strip()

    try:
        validate_status_value(status_value)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        cursor.execute("SELECT label, url FROM links WHERE status = ?", (status_value,))
        rows = cursor.fetchall()

    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)
    finally:
        if conn:
            conn.close()

    try:
        with open(output_path, 'w') as f:
            f.write("<html><head><title>Link report</title></head><body>\n")
            f.write("<table><tr><th>Label</th><th>URL</th><th>Status</th></tr>\n")

            for label, url in rows:
                try:
                    response = requests.get(url, timeout=5)
                    status_code = response.status_code
                except requests.RequestException:
                    status_code = "Error"

                f.write(f"<tr><td>{escape(label)}</td><td>{escape(url)}</td><td>{status_code}</td></tr>\n")
                time.sleep(1)  # Rate limiting to prevent DoS

            f.write("</table></body></html>")

    except IOError as e:
        print(f"File error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import sqlite3
import re
import requests
import ast
import operator
import os
from urllib.parse import urlparse

def evaluate_expression(expr):
    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left // right
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
        elif isinstance(node, ast.Num):
            return node.n
        raise ValueError("Unsupported operation")

    tree = ast.parse(expr, mode='eval')
    return eval_node(tree.body)

def replace_placeholders(query, values):
    def replacer(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))
    return re.sub(r'\{\{(.*?)\}\}', replacer, query)

def run_check(check):
    name = check['name']
    db_path = check['db']
    query = check['query']
    threshold = check['threshold']
    webhook = check['webhook']

    try:
        if not os.path.isfile(db_path):
            raise ValueError("Database file does not exist")

        if not urlparse(webhook).scheme.startswith('https'):
            raise ValueError("Webhook URL must use HTTPS")

        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        query = replace_placeholders(query, {})
        cursor.execute(query)
        result = cursor.fetchone()
        conn.close()

        if result is None or len(result) == 0:
            value = 0
        else:
            value = int(result[0])

        if value > threshold:
            payload = {"check": name, "value": value}
            response = requests.post(webhook, json=payload, headers={'Content-Type': 'application/json'}, verify=True)
            if response.status_code < 400:
                outcome = 'sent'
            else:
                outcome = 'failed'
        else:
            outcome = 'skipped'

        print(f"{name} {value} {outcome}")

    except Exception as e:
        print(f"{name} 0 failed")

def main():
    if len(sys.argv) != 2:
        print("Usage: python alertcheck.py checks.json")
        sys.exit(1)

    config_path = sys.argv[1]
    if not os.path.isfile(config_path):
        print("Configuration file does not exist")
        sys.exit(1)

    with open(config_path, 'r') as f:
        try:
            config = json.load(f)
        except json.JSONDecodeError:
            print("Invalid JSON format")
            sys.exit(1)

    if 'checks' not in config or not isinstance(config['checks'], list):
        print("Invalid configuration format")
        sys.exit(1)

    for check in config['checks']:
        if not all(k in check for k in ("name", "db", "query", "threshold", "webhook")):
            print(f"Invalid check format: {check}")
            continue
        run_check(check)

if __name__ == "__main__":
    main()

import sys
import sqlite3
import html
import re

def validate_columns(columns):
    if not columns:
        return False
    return all(re.match(r'^[a-zA-Z0-9_]+$', col) for col in columns)

def main():
    if len(sys.argv) != 5:
        sys.exit(2)

    db_path, table_name, columns, token = sys.argv[1:]
    columns = columns.split(',')

    if not validate_columns(columns):
