import sys
import sqlite3
import json
import html
import hashlib
import os
import re

def read_file(file_path):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")
    with open(file_path, 'r') as file:
        return file.read()

def write_file(file_path, content):
    with open(file_path, 'w') as file:
        file.write(content)

def replace_placeholders(template, replacements):
    for key, value in replacements.items():
        template = re.sub(r'\{\{' + re.escape(key) + r'\}\}', value, template)
    return template

def escape_html(value):
    return html.escape(str(value), quote=True)

def sanitize_json(json_data):
    if not isinstance(json_data, dict):
        raise ValueError("JSON data must be an object")
    return {k: str(v) for k, v in json_data.items()}

def main():
    if len(sys.argv) != 5:
        print("Usage: python report.py <database> <query_file> <json_file> <output_file>")
        sys.exit(1)

    db_path, query_file_path, json_file_path, output_file_path = sys.argv[1:]

    if not os.path.isfile(db_path):
        raise FileNotFoundError(f"Database file not found: {db_path}")

    query = read_file(query_file_path)
    json_data = json.loads(read_file(json_file_path))
    json_data = sanitize_json(json_data)

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    try:
        cursor.execute(query, {k: json_data.get(k, '') for k in re.findall(r'\{\{(\w+)\}\}', query)})
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)
    finally:
        conn.close()

    table_html = "<table>"
    for row in rows:
        table_html += "<tr>"
        for value in row:
            table_html += f"<td>{escape_html(value)}</td>"
        table_html += "</tr>"
    table_html += "</table>"

    html_template = "<html><body>{{table}}</body></html>"
    rendered_html = replace_placeholders(html_template, {"table": table_html})

    write_file(output_file_path, rendered_html)

    html_hash = hashlib.sha256(rendered_html.encode('utf-8')).hexdigest()
    print(html_hash)

if __name__ == "__main__":
    main()

import sys
import json
import requests
import xml.etree.ElementTree as ET
from xml.etree.ElementTree import ParseError
from urllib.parse import urlparse
import os

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def is_safe_path(path):
    return os.path.abspath(path) == os.path.normpath(path)

def main():
    if len(sys.argv) != 2:
        print("Usage: python feed_digest.py <config_file>")
        sys.exit(1)

    config_path = sys.argv[1]

    if not is_safe_path(config_path):
        print("Invalid file path.")
        sys.exit(1)

    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (json.JSONDecodeError, FileNotFoundError):
        print("Invalid or missing configuration file.")
        sys.exit(1)

    feeds = config.get("feeds", [])
    result = {"feeds": []}

    for feed in feeds:
        feed_name = feed.get("name")
        feed_url = feed.get("url")
        feed_result = {"name": feed_name}

        if not is_valid_url(feed_url):
            feed_result["error"] = "failed"
        else:
            try:
                response = requests.get(feed_url, verify=True)
                response.raise_for_status()
                parser = ET.XMLParser(forbid_dtd=True)
                root = ET.fromstring(response.content, parser=parser)

                first_item = root.find(".//item")
                if first_item is not None:
                    title = first_item.find("title")
                    link = first_item.find("link")
                    if title is not None and link is not None:
                        feed_result["title"] = title.text
                        feed_result["link"] = link.text
                    else:
                        feed_result["error"] = "failed"
                else:
                    feed_result["error"] = "failed"
            except (requests.RequestException, ParseError):
                feed_result["error"] = "failed"

        result["feeds"].append(feed_result)

    print(json.dumps(result))

if __name__ == "__main__":
    main()

import sys
import json
import re
import ast
import operator

def evaluate_expression(expr):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.USub: operator.neg,
        ast.Num: lambda n: n.n
    }

    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return allowed_operators[type(node.op)](operand)
        elif isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    try:
        tree = ast.parse(expr, mode='eval')
        return eval_node(tree.body)
    except (SyntaxError, ValueError):
        raise ValueError("Invalid expression")

def process_steps(steps):
    pattern = r'\{\{([^{}]+)\}\}'
    for step in steps:
        processed = re.sub(pattern, lambda m: str(evaluate_expression(m.group(1))), step)
        print(processed)

def main():
    if len(sys.argv) != 2:
        print("Usage: python taskrun.py <file_path>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            data = json.load(file)
    except (json.JSONDecodeError, FileNotFoundError):
        print("Error: Invalid JSON or file not found", file=sys.stderr)
        sys.exit(1)

    token = data.get('token', {})
    steps = data.get('steps', [])

    if token.get('user') != 'runner' or 'run' not in token.get('scopes', []):
        print("ACCESS DENIED", file=sys.stderr)
        sys.exit(3)

    process_steps(steps)
    sys.exit(0)

if __name__ == "__main__":
    main()

import os
import sys
import xml.etree.ElementTree as ET
import json
import hashlib
from xml.etree.ElementTree import ParseError
from pathlib import Path

def check_env_var():
    if 'CONFIG_CACHE_KEY' not in os.environ:
        sys.stderr.write('config.cache: missing key\n')
        sys.exit(1)

def compute_tag(values, key):
    serialized = ''.join(values)
    return hashlib.sha256((serialized + key).encode()).hexdigest()

def validate_xml_structure(root):
    required_tags = ['host', 'port', 'username', 'password', 'database']
    if root.tag != 'config' or any(root.find(tag) is None for tag in required_tags):
        raise ValueError("Invalid XML structure")
    return [root.find(tag).text for tag in required_tags]

def pack(xml_path, cache_path):
    check_env_var()
    xml_path = Path(xml_path).resolve()
    cache_path = Path(cache_path).resolve()

    if not xml_path.is_file():
        sys.stderr.write('config.cache: XML file not found\n')
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        values = validate_xml_structure(root)
    except (ParseError, ValueError) as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

    tag = compute_tag(values, os.environ['CONFIG_CACHE_KEY'])
    try:
        with open(cache_path, 'w') as f:
            f.write(f"{tag}\n")
            f.write('\n'.join(values))
    except IOError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

def unpack(cache_path):
    check_env_var()
    cache_path = Path(cache_path).resolve()

    if not cache_path.is_file():
        sys.stderr.write('config.cache: Cache file not found\n')
        sys.exit(1)

    try:
        with open(cache_path, 'r') as f:
            stored_tag = f.readline().strip()
            values = [f.readline().strip() for _ in range(5)]
    except IOError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

    try:
        recomputed_tag = compute_tag(values, os.environ['CONFIG_CACHE_KEY'])
        if recomputed_tag != stored_tag:
            sys.stderr.write('config.cache: tag mismatch\n')
            sys.exit(1)
        result = {
            'host': values[0],
            'port': int(values[1]),
            'username': values[2],
            'password': values[3],
            'database': values[4]
        }
        print(json.dumps(result))
    except ValueError as e:
        sys.stderr.write(f'config.cache: {str(e)}\n')
        sys.exit(1)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        sys.exit(1)
    command = sys.argv[1]
    if command == 'pack' and len(sys.argv) == 4:
        pack(sys.argv[2], sys.argv[3])
    elif command == 'unpack' and len(sys.argv) == 3:
        unpack(sys.argv[2])
    else:
        sys.exit(1)

import sys
import os
import json
import xml.etree.ElementTree as ET
from xml.etree.ElementTree import ParseError
from xml.parsers.expat import ExpatError

def load_dictionary_from_xml(xml_path):
    try:
        # Use a parser that does not process external entities
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(xml_path, parser=parser)
        root = tree.getroot()
        dictionary = {entry.get('key'): entry.get('value') for entry in root.findall('entry')}
        return dictionary
    except (ParseError, ExpatError) as e:
        sys.stderr.write(f"error: {xml_path}\n")
        sys.exit(1)

def load_dictionary_from_cache(cache_path):
    try:
        with open(cache_path, 'r') as cache_file:
            return json.load(cache_file)
    except (IOError, json.JSONDecodeError) as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

def save_dictionary_to_cache(cache_path, dictionary):
    try:
        with open(cache_path, 'w') as cache_file:
            json.dump(dictionary, cache_file, indent=2)
        # Set secure file permissions
        os.chmod(cache_path, 0o600)
    except IOError as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write(f"error: {sys.argv[0]}\n")
        sys.exit(1)

    config_path = sys.argv[1]
    if not os.path.isfile(config_path):
        sys.stderr.write(f"error: {config_path}\n")
        sys.exit(1)

    # Normalize the path to prevent path traversal
    config_path = os.path.abspath(config_path)
    cache_path = config_path + '.cache'

    if os.path.exists(cache_path):
        dictionary = load_dictionary_from_cache(cache_path)
        source = "cache"
    else:
        dictionary = load_dictionary_from_xml(config_path)
        save_dictionary_to_cache(cache_path, dictionary)
        source = "xml"

    print(json.dumps(dictionary, indent=2))
    sys.stderr.write(f"source={source}\n")

if __name__ == "__main__":
    main()

import json
import hashlib
import html
import os

def main():
    try:
        with open('data.bin', 'rb') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        return

    if not isinstance(data, dict) or 'salt' not in data or 'users' not in data:
        return

    salt = data['salt']
    users = data['users']

    if not isinstance(salt, str) or not isinstance(users, list):
        return

    html_content = ['<table>', '<tr><th>Name</th><th>Email Hash</th></tr>']

    for user in users:
        if not isinstance(user, dict) or 'name' not in user or 'email' not in user:
            continue

        name = html.escape(user['name'])
        email = html.escape(user['email'])
        email_hash = hashlib.sha256((salt + email).encode()).hexdigest()
        html_content.append(f'<tr><td>{name}</td><td>{email_hash}</td></tr>')

    html_content.append('</table>')

    try:
        with open('report.html', 'w') as f:
            f.write('\n'.join(html_content))
    except IOError:
        return

if __name__ == '__main__':
    main()

import sys
