        sys.stderr.write('Request timed out\n')
        sys.exit(1)
    except requests.exceptions.RequestException as e:
        sys.stderr.write(f'Network error: {e}\n')
        if os.path.exists('last_quote.txt'):
            with open('last_quote.txt', 'r') as quote_file:
                print(quote_file.read())
            sys.exit(0)
        else:
            sys.stderr.write('no cached quote\n')
            sys.exit(1)

if __name__ == '__main__':
    main()

import os
import sys
import json
import urllib.request
import ssl
import signal
from http.client import HTTPException

def fetch_formulas():
    formula_url = os.getenv('FORMULA_URL')
    formula_token = os.getenv('FORMULA_TOKEN')

    if not formula_url or not formula_token:
        print("Environment variables FORMULA_URL and FORMULA_TOKEN must be set.", file=sys.stderr)
        sys.exit(1)

    headers = {'Authorization': f'Bearer {formula_token}'}
    req = urllib.request.Request(formula_url, headers=headers)

    try:
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE

        with urllib.request.urlopen(req, context=context, timeout=10) as response:
            if response.status != 200:
                print("fetch failed", file=sys.stderr)
                sys.exit(1)
            return json.loads(response.read().decode())
    except (HTTPException, ValueError, ssl.SSLError, urllib.error.URLError) as e:
        print("fetch failed", file=sys.stderr)
        sys.exit(1)

def safe_eval(expr, a, b):
    allowed_names = {
        '__builtins__': None,
        'a': a,
        'b': b
    }
    try:
        return eval(expr, {"__builtins__": None}, allowed_names)
    except Exception:
        return None

def evaluate_formulas(formulas):
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            a, b = map(float, line.split())
        except ValueError:
            continue

        for name, expression in formulas.items():
            value = safe_eval(expression, a, b)
            if value is not None:
                print(f"{name}={repr(value)}")

def handle_timeout(signum, frame):
    raise TimeoutError

if __name__ == "__main__":
    signal.signal(signal.SIGALRM, handle_timeout)
    signal.alarm(30)  # Set a 30-second timeout for the entire script

    try:
        formulas = fetch_formulas()
        evaluate_formulas(formulas)
    except TimeoutError:
        print("Operation timed out", file=sys.stderr)
        sys.exit(1)
    finally:
        signal.alarm(0)

    sys.exit(0)

import sys
import json
import requests
from datetime import datetime
import os
import time

def fetch_users(config_path, ids_path, out_path):
    if len(sys.argv) != 4:
        print("Usage: python fetch_users.py <config_path> <ids_path> <out_path>")
        sys.exit(1)

    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading config file: {e}")
        sys.exit(1)

    if 'base_url' not in config or 'api_token' not in config:
        print("Config file must contain 'base_url' and 'api_token'")
        sys.exit(1)

    base_url = config['base_url']
    api_token = config['api_token']

    if not os.path.isfile(ids_path):
        print(f"Error: {ids_path} does not exist")
        sys.exit(1)

    if os.path.exists(out_path):
        print(f"Warning: {out_path} already exists and will be overwritten")

    try:
        with open(ids_path, 'r') as ids_file, open(out_path, 'w', encoding='utf-8') as out_file:
            for user_id in ids_file:
                user_id = user_id.strip()
                if not user_id:
                    continue
                url = f"{base_url.rstrip('/')}/users/{user_id}"
                headers = {'Authorization': f'Bearer {api_token}'}

                try:
                    response = requests.get(url, headers=headers, timeout=10, allow_redirects=True)
                    status_code = response.status_code
                except requests.RequestException as e:
                    print(f"Request failed for {user_id}: {e}")
                    status_code = 'ERROR'

                out_file.write(f"{user_id} {status_code}\n")

                timestamp = datetime.utcnow().isoformat(timespec='seconds') + 'Z'
                with open('fetch.log', 'a', encoding='utf-8') as log_file:
                    log_file.write(f"{timestamp} {user_id} {status_code}\n")

                time.sleep(0.1)  # Basic rate limiting

    except IOError as e:
        print(f"Error writing to file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    fetch_users(sys.argv[1], sys.argv[2], sys.argv[3])

import sys
import xml.etree.ElementTree as ET
import requests
import re
import logging
from lxml import etree
from xml.etree.ElementTree import ParseError
from requests.exceptions import RequestException
import time

logging.basicConfig(level=logging.INFO)

def parse_config(file_path):
    config = {}
    with open(file_path, 'r') as file:
        for line in file:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=', 1)
                config[key.strip()] = value.strip()
    return config

def fetch_and_sum_prices(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        parser = etree.XMLParser(resolve_entities=False, no_network=True)
        root = etree.fromstring(response.content, parser)
        prices = root.xpath('.//price')
        return sum(float(price.text) for price in prices if price.text and re.match(r'^\d+(\.\d+)?$', price.text))
    except (RequestException, ParseError, ValueError) as e:
        logging.error(f"Error fetching or parsing XML: {e}")
        sys.exit(1)

def evaluate_threshold(threshold):
    try:
        return eval(re.sub(r'(\d+\.\d+|\d+)', r'float(\1)', threshold), {"__builtins__": None}, {})
    except Exception as e:
        logging.error(f"Error evaluating threshold: {e}")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file>")
        sys.exit(1)

    config = parse_config(sys.argv[1])
    feed_url = config.get('feed_url')
    threshold = config.get('threshold')

    if not feed_url or not threshold:
        print("Error: Missing feed_url or threshold in config file")
        sys.exit(1)

    total_price = fetch_and_sum_prices(feed_url)
    threshold_value = evaluate_threshold(threshold)

    print("OK" if total_price > threshold_value else "LOW")

if __name__ == "__main__":
    main()

import os
import time
import json
import uuid
import requests
from datetime import datetime, timezone
from urllib.parse import urlparse
import logging

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def poll_health_endpoint():
    health_url = os.environ.get('HEALTH_URL')
    if not health_url or not is_valid_url(health_url):
        raise ValueError("Invalid or missing HEALTH_URL environment variable")

    logging.basicConfig(filename='health.log', level=logging.INFO, format='%(message)s')

    while True:
        try:
            response = requests.get(health_url, timeout=10, verify=True)
            response.raise_for_status()
            data = response.json()

            if 'service' in data and 'status' in data:
                log_entry = {
                    'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                    'service': data['service'],
                    'status': data['status'],
                    'request_id': uuid.uuid4().hex
                }
            else:
                raise ValueError("Response JSON missing required fields")

        except requests.RequestException as e:
            log_entry = {
                'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                'error': str(e)
            }
        except (ValueError, json.JSONDecodeError) as e:
            log_entry = {
                'timestamp': datetime.now(timezone.utc).isoformat(timespec='milliseconds') + 'Z',
                'error': "Invalid response format"
            }

        logging.info(json.dumps(log_entry))
        time.sleep(10)

if __name__ == "__main__":
    poll_health_endpoint()

import sys
import urllib.request
import json
import re
import ssl
import html
import time
from urllib.parse import urlparse

def fetch_json(url):
    context = ssl.create_default_context()
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE
    try:
        with urllib.request.urlopen(url, context=context, timeout=10) as response:
            return json.loads(response.read().decode())
    except Exception as e:
        raise RuntimeError(f"Failed to fetch JSON from {url}: {e}")

def evaluate_expression(expression, context):
    allowed_names = {k: v for k, v in context.items() if isinstance(v, (int, float))}
    try:
        return str(eval(expression, {"__builtins__": None}, allowed_names))
    except Exception:
        return ''

def render_template(template, context):
    pattern = re.compile(r'\{\{(.+?)\}\}')
    return pattern.sub(lambda m: html.escape(evaluate_expression(m.group(1), context)), template)

def validate_url(url):
    parsed_url = urlparse(url)
    if parsed_url.scheme not in ('http', 'https'):
        raise ValueError("Invalid URL scheme. Only http and https are allowed.")

def main():
    if len(sys.argv) != 3:
        print("Usage: python report_renderer.py <url> <template_file>")
        sys.exit(1)

    url, template_file = sys.argv[1], sys.argv[2]

    try:
        validate_url(url)
        json_data = fetch_json(url)
        with open(template_file, 'r') as file:
            template = file.read()
        rendered_html = render_template(template, json_data)
        print(rendered_html)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import re
import html

def is_valid_name(name):
    return re.match(r'^[a-zA-Z0-9_]+$', name) is not None

def is_valid_formula(formula, context):
    allowed_names = set(context.keys())
    allowed_operators = {'+', '-', '*', '/', '//', '%', '**', '(', ')'}
    tokens = re.findall(r'\b\w+\b|[+\-*/%()]+', formula)
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            continue
        if token in allowed_names or token in allowed_operators:
            continue
        return False
    return True

def evaluate_formula(formula, context):
    try:
        return eval(formula, {"__builtins__": None}, context)
    except Exception as e:
        return f"Error: {e}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python formula_report.py report.xml")
        return

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print("Error: Could not parse XML file.")
        return
    except FileNotFoundError:
        print("Error: XML file not found.")
        return

    context = {}
    print("<table>")
    print("<tr><th>field</th><th>value</th></tr>")

    for field in root.findall('field'):
        name = field.get('name')
        formula = field.get('formula')
        if not name or not formula:
            continue
        if not is_valid_name(name):
            print(f"<tr><td>{html.escape(name)}</td><td>Error: Invalid field name</td></tr>")
            continue
        if not is_valid_formula(formula, context):
            print(f"<tr><td>{html.escape(name)}</td><td>Error: Invalid formula</td></tr>")
            continue
        value = evaluate_formula(formula, context)
        context[name] = value
        print(f"<tr><td>{html.escape(name)}</td><td>{html.escape(str(value))}</td></tr>")

    print("</table>")

if __name__ == "__main__":
    main()

import sys
import re
import time
import ast
import operator
from math import isfinite

def evaluate_expression(expression):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            if not isfinite(node.n):
                raise ValueError("Non-finite number")
            return node.n
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            if isinstance(node.op, ast.Div):
                raise ValueError("Division is not allowed")
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return allowed_operators[type(node.op)](operand)
        else:
            raise ValueError("Unsupported operation")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def process_line(line, line_number):
    pattern = re.compile(r'\{\{(.+?)\}\}')
    matches = list(pattern.finditer(line))
    if not matches:
        return line

    new_line = line
    offset = 0
    for match in matches:
        expression = match.group(1).strip()
        try:
            result = evaluate_expression(expression)
            new_line = new_line[:match.start() - offset] + str(result) + new_line[match.end() - offset:]
            offset += len(str(result)) - len(match.group(0))
        except Exception as e:
            sys.stderr.write(f"line {line_number}: {str(e)}\n")
            return line
    return new_line

def main():
    error_count = 0
    line_number = 0

    for line in sys.stdin:
        line_number += 1
        if line_number > 1:
            time.sleep(0.2)

        processed_line = process_line(line, line_number)
        sys.stdout.write(processed_line)
        if processed_line != line:
            error_count += 1

    if error_count > 0:
        sys.stderr.write(f"errors: {error_count}\n")

if __name__ == "__main__":
    main()
